"use client"
import type React from "react"
import type { Metadata } from "next"
import { Playfair_Display, Inter } from "next/font/google"
import { Analytics } from "@vercel/analytics/next"
import "./globals.css"
import { CartProvider } from "@/components/CartContext";
import { Toaster } from "sonner";
import { UpdateCartContext } from "./_context/UpdateCartContext"

import { useState } from "react"

const playfair = Playfair_Display({
  subsets: ["latin"],
  variable: "--font-serif",
})

const inter = Inter({
  subsets: ["latin"],
  variable: "--font-sans",
})

export const metadata: Metadata = {
  title: "Ms V's Body Pleasures - Artisan Soaps & Wellness Products",
  description:
    "Elevate your daily routine into an extraordinary and delightful wellness journey with our handcrafted artisan soaps, body butters, bath bombs, and more.",
  generator: "v0.app",
  icons: {
    icon: [
      {
        url: "/icon-light-32x32.png",
        media: "(prefers-color-scheme: light)",
      },
      {
        url: "/icon-dark-32x32.png",
        media: "(prefers-color-scheme: dark)",
      },
      {
        url: "/icon.svg",
        type: "image/svg+xml",
      },
    ],
    apple: "/apple-icon.png",
  },
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  const [updateCart, setUpdateCart] = useState(false);
  return (
    <html lang="en">
      <body className={`${inter.variable} ${playfair.variable} font-sans antialiased`} suppressHydrationWarning={true}>
        <UpdateCartContext.Provider value={{updateCart, setUpdateCart}}>
          {children}
       
        <Toaster position="top-right" />
        </UpdateCartContext.Provider>
        <Analytics />
      </body>
    </html>
  )
}
